INSERT INTO `knowledge_interface` (`id`, `service_id`, `method`, `path`, `name`, `description`, `request_content_type`, `response_content_type`) VALUES ('328937da8e00ed87','328937da8dfbed87','POST','/api/v1/reports/summary','顶部指标统计','获取当前筛选范围的顶部指标及机构基准','application/json','application/json');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328937da8e01ed87','LQ13.03','zhituo','BUSINESS_RULE','检索框下的指标统计组件ID为kpiStrip，数据通过统计接口获取。统计内容包括生效中规划、涉及技能、当日或周期任务数、推荐客户数、方案被查看率和接触率，以及覆盖支行、使用人数最多技能、人均数量和机构基准差值。','file:///Users/natasha/Downloads/智拓报表.html；指标条section与renderKPI','CONFIRMED','顶部指标业务用途','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328937da8e02ed87','LQ13.03','zhituo','BUSINESS_RULE','指标统计按当前日期区间、分行、支行、客户经理等级和技能条件调用接口获取结果。单日与多日分别对应当日和周期统计；机构基准用于比较当前范围与所选分行整体水平。','file:///Users/natasha/Downloads/智拓报表.html；renderKPI、filteredManagers、renderAll','CONFIRMED','顶部指标检索行为','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328937da8e0eed87','LQ13.03','zhituo','TECHNICAL_RULE','当前顶部统计由MySQL显式JOIN和非递归CTE完成执行范围选择、去重和聚合，仅向Java返回汇总结果。Java计算比率、精确差值并组装响应；当前范围与机构基准独立聚合。执行时间并列时按执行主键倒序取一条。已有功能对照记录不代表所有后续改动已验证，也不代表已达到性能预算。','docs/report-api.md 统计实现说明；docs/report-summary-sql-validation.md','CONFIRMED','顶部统计SQL实现','TECHNICAL');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328937da8e0fed87','LQ13.03','zhituo','CONFLICT','页面业务说明与当前后端契约存在待确认的口径差异：页面生效中规划说明按当前状态、不受日期影响且按规划负责人机构归集；后端按排程及执行范围、目标客户经理机构，不额外限制生效状态。页面任务数解释为下发任务，后端taskCount表示成功推荐客户方案数，另有scheduledTaskCount等任务指标。页面接触解释为有效接通、到店或线上互动，后端按接触明细关联去重，不附加有效接通条件。页面数据按接口获取，聚合与去重以接口业务契约为依据。后续需求澄清应明确这些业务口径的取舍，不自动修改现有实现。','file:///Users/natasha/Downloads/智拓报表.html 指标口径、页脚及aggManagers；docs/report-api.md；docs/knowledge/shared/report-rules.md','PENDING','页面业务说明与接口口径差异','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e00584ed87','LQ13.03','zhituo','BUSINESS_RULE','所选排程日期含首尾。排程表示计划安排，不等于已经执行；常规指标只统计已执行范围，任务执行补充指标包含未执行任务。','docs/knowledge/shared/report-rules.md RULE_DATE、RULE_TASK；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e03ed87','CONFIRMED','统计日期与执行范围','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e00587ed87','LQ13.03','zhituo','BUSINESS_RULE','实际执行日期匹配execute_day且不早于规划创建时间。每任务每天取最新执行记录；时间并列按执行主键倒序。','docs/knowledge/shared/report-rules.md RULE_DATE、RULE_TASK；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e03ed87','CONFIRMED','执行记录选择','TECHNICAL');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e0058aed87','LQ13.03','zhituo','BUSINESS_RULE','机构按目标客户经理归属；分行、支行、等级单选，技能多选取或。各范围独立去重，不能累加每日或子维度数值替代整体。','docs/knowledge/shared/report-rules.md RULE_SCOPE；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e04ed87','CONFIRMED','顶部指标筛选与去重','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e0058ded87','LQ13.03','zhituo','BUSINESS_RULE','bbkId、orgId、level省略、null、空字符串视为未筛选；skillIds省略、null、空数组表示全部。不校验分支行归属，正常执行查询。','docs/knowledge/shared/report-rules.md RULE_SCOPE；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e04ed87','CONFIRMED','筛选参数处理','TECHNICAL');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e00590ed87','LQ13.03','zhituo','METRIC_RULE','规划数为当前执行范围的规划去重数，覆盖支行按分行和支行组合去重。当前接口不额外按生效状态或有效期筛选，不套用规划覆盖模块的三类来源限制。','docs/report-api.md 顶部统计及通用约定；docs/knowledge/modules/reports.md；docs/knowledge/shared/report-rules.md RULE_DATE；拆分来源知识ID=328937da8e05ed87','CONFIRMED','规划和覆盖支行业务口径','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e00593ed87','LQ13.03','zhituo','METRIC_RULE','planCount按规划编号去重；coveredSubBranchCount按(bbkId,orgId)组合去重；统计归属来自目标客户经理，不使用负责人机构。','docs/report-api.md 顶部统计及通用约定；docs/knowledge/modules/reports.md；docs/knowledge/shared/report-rules.md RULE_DATE；拆分来源知识ID=328937da8e05ed87','CONFIRMED','规划与机构去重实现','TECHNICAL');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e00596ed87','LQ13.03','zhituo','METRIC_RULE','技能数按技能编号去重；使用人数最多技能按客户经理去重人数排名，人数并列按技能编号升序，无数据为空。','docs/report-api.md 顶部统计响应字段和统计实现说明；拆分来源知识ID=328937da8e06ed87','CONFIRMED','技能数量与最广使用技能','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e00599ed87','LQ13.03','zhituo','METRIC_RULE','同一技能编号出现多个名称时，当前SQL选取名称最小值，仅影响名称展示，不作为新的业务标识。','docs/report-api.md 顶部统计响应字段和统计实现说明；拆分来源知识ID=328937da8e06ed87','CONFIRMED','技能名称冲突处理','TECHNICAL');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e0059ced87','LQ13.03','zhituo','METRIC_RULE','成功推荐客户方案按客户方案计数，与任务数量单位不同。应执行=已执行+待执行；失败也属于已执行。待执行不区分未来未到期与到期未执行。客户方案数可以大于任务数。','docs/knowledge/shared/report-rules.md RULE_TASK、RULE_RESULT；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e07ed87','CONFIRMED','任务与客户方案计量口径','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e0059fed87','LQ13.03','zhituo','METRIC_RULE','taskCount筛选result_type=plan、最新成功标记=1、结果状态SUC且custuid非空，按(trace_id,custuid)去重。scheduledTaskCount按目标工号、规划、技能、排程日、任务去重；存在执行即executedTaskCount，无执行为pendingTaskCount，最新status非success为failedTaskCount。','docs/knowledge/shared/report-rules.md RULE_TASK、RULE_RESULT；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e07ed87','CONFIRMED','任务及成功方案实现','TECHNICAL');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e005a2ed87','LQ13.03','zhituo','METRIC_RULE','推荐客户按当前范围整体去重，跨技能同一客户只计一次；人均客户方案数和人均推荐客户数分别除以执行客户经理人数，无人员时为空。','docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e08ed87','CONFIRMED','推荐客户与人均口径','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e005a5ed87','LQ13.03','zhituo','METRIC_RULE','recommendedCustomerCount按成功推荐结果中非空custuid去重；averageTaskCount=taskCount/userCount，averageRecommendedCustomerCount=recommendedCustomerCount/userCount。Java以BigDecimal及HALF_UP取整数。','docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e08ed87','CONFIRMED','推荐客户与人均实现','TECHNICAL');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e005a8ed87','LQ13.03','zhituo','METRIC_RULE','查看率为已查看方案客户数除以推荐客户数；客户在当前范围去重，推荐客户为0时比率为空。','docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e09ed87','CONFIRMED','方案查看率业务口径','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e005abed87','LQ13.03','zhituo','METRIC_RULE','viewRate将is_read=1执行对应的成功推荐客户去重数除以recommendedCustomerCount并乘100。','docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e09ed87','CONFIRMED','方案查看率计算实现','TECHNICAL');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e005aeed87','LQ13.03','zhituo','METRIC_RULE','接触率以推荐客户数为分母，当前接口按关联接触明细中的客户去重，未附加接通等有效性条件，允许超过100%。','docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e0aed87','CONFIRMED','接触率业务口径','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e005b1ed87','LQ13.03','zhituo','METRIC_RULE','接触通过click_event_id关联点击；事件为button_click或preview_view且template_type=sub。trace_id匹配执行，customer_id匹配推荐客户，点击与执行同日；cust_uid忽略NULL保留空字符串，不额外等于推荐客户标识；contactRate=接触客户去重数/推荐客户数×100。','docs/knowledge/shared/report-rules.md RULE_CUSTOMER、RULE_RATE；docs/report-api.md 通用约定；拆分来源知识ID=328937da8e0aed87','CONFIRMED','接触明细关联实现','TECHNICAL');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e005b4ed87','LQ13.03','zhituo','BUSINESS_RULE','基准保留日期及分行，移除支行、等级、技能；按整体去重数据计算，不平均支行率。差值为当前率减机构基准率，单位百分点。','docs/knowledge/shared/report-rules.md RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e0bed87','CONFIRMED','机构基准与差值业务口径','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e005b7ed87','LQ13.03','zhituo','BUSINESS_RULE','benchmarkViewRate、benchmarkContactRate独立聚合计算；viewRateDifference及contactRateDifference使用双方未舍入值相减，任一分母为0则差值为null。','docs/knowledge/shared/report-rules.md RULE_RATE；docs/report-api.md 顶部统计；拆分来源知识ID=328937da8e0bed87','CONFIRMED','机构基准差值实现','TECHNICAL');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e005baed87','LQ13.03','zhituo','TECHNICAL_RULE','数量无数据为0，分母为0时比率为空。比率返回百分比数值，百分比和百分点差值保留两位，人均值取整数。','docs/knowledge/shared/report-rules.md RULE_RATE；docs/report-api.md 通用约定与顶部统计；拆分来源知识ID=328937da8e0ced87','CONFIRMED','数值单位与空值约定','BUSINESS');
INSERT INTO `knowledge_entry` (`id`, `system_code`, `project_code`, `kind`, `content`, `source`, `status`, `title`, `knowledge_type`) VALUES ('328940e005bded87','LQ13.03','zhituo','TECHNICAL_RULE','Java使用BigDecimal与HALF_UP；JSON数值不保证尾随零，差值以未舍入值计算后舍入，不使用已舍入展示值。','docs/knowledge/shared/report-rules.md RULE_RATE；docs/report-api.md 通用约定与顶部统计；拆分来源知识ID=328937da8e0ced87','CONFIRMED','数值精度实现','TECHNICAL');
